import type { ICtx, ScheduleHandle } from "@threenative/core";
import { CharacterBody3D, CollisionShape3D, type IPhysicsContext } from "@threenative/physics";
import { type Group, Vector3 } from "three";
import { directSpaceState } from "../physics.js";
import { createEnemyVisual } from "../render/shapes.js";
import type { GameState } from "../state.js";
import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";

type GameCtx = ICtx<GameState, IPhysicsContext>;

const PATROL_SPEED = 2.5;
const CHASE_SPEED = 3.8;
const DETECTION_RANGE = 8;
const FIRE_COOLDOWN = 4;
const SCAN_INTERVAL_RANGE = [3, 8] as const;

export class Enemy {
  readonly mesh: Group;
  readonly body: CharacterBody3D;
  readonly tags = ["hostile", "enemy"];
  readonly wave: number | undefined;
  health: number;
  alive = true;
  detected = false;
  #scanHandle: ScheduleHandle | undefined;
  #fireTimer = 0;
  #onFire: (origin: Vector3) => void;
  #scanShape = CollisionShape3D.sphere(DETECTION_RANGE);
  #patrolPoints: Vector3[];
  #currentPatrolIndex = 0;
  #moveDirection = new Vector3();

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createEnemyVisual>[0],
    position: Vector3,
    patrolPoints: Vector3[],
    options: {
      readonly health?: number;
      readonly onFire?: (origin: Vector3) => void;
      readonly wave?: number;
    } = {},
  ) {
    this.wave = options.wave;
    this.health = options.health ?? 50;
    this.#onFire = options.onFire ?? (() => undefined);
    this.#patrolPoints = patrolPoints.length > 0 ? patrolPoints : [position.clone()];
    this.mesh = createEnemyVisual(materials);
    this.mesh.position.copy(position);
    ctx.add(this.mesh);
    this.body = new CharacterBody3D({
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER | PLAYER_LAYER,
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(0.45, 0.38),
    });
  }

  startScanning(ctx: GameCtx, playerBodyId: number): void {
    const scan = (): void => {
      if (!this.alive) return;
      const hits = directSpaceState(ctx.physics).intersectShape({
        collisionMask: PLAYER_LAYER,
        maxResults: 4,
        position: this.mesh.position,
        shape: this.#scanShape,
      });
      this.detected = hits.some((hit) => hit.body.id === playerBodyId);
      const [min, max] = SCAN_INTERVAL_RANGE;
      this.#scanHandle = ctx.after(ctx.random.range(min, max) / 60, scan);
    };
    const [min, max] = SCAN_INTERVAL_RANGE;
    this.#scanHandle = ctx.after(ctx.random.range(min, max) / 60, scan);
  }

  update(ctx: GameCtx, dt: number, playerPosition: Vector3): void {
    if (!this.alive) return;

    if (this.detected) {
      this.#updateChase(playerPosition);
    } else {
      this.#updatePatrol();
    }

    this.body.moveAndSlide(dt);

    this.#fireTimer -= dt;
    if (this.detected && this.#fireTimer <= 0) {
      this.#fireTimer = FIRE_COOLDOWN;
      this.#onFire(this.mesh.position.clone().add(new Vector3(0.3, 0.9, 0)));
    }
  }

  #updatePatrol(): void {
    const patrol = this.#patrolPoints[this.#currentPatrolIndex];
    if (patrol === undefined) return;

    const distance = this.mesh.position.distanceTo(patrol);
    if (distance < 0.5) {
      this.#currentPatrolIndex = (this.#currentPatrolIndex + 1) % this.#patrolPoints.length;
      return;
    }

    this.#moveDirection.copy(patrol).sub(this.mesh.position).normalize();
    this.body.velocity.x = this.#moveDirection.x * PATROL_SPEED;
    this.body.velocity.z = this.#moveDirection.z * PATROL_SPEED;
  }

  #updateChase(playerPosition: Vector3): void {
    this.#moveDirection.copy(playerPosition).sub(this.mesh.position).normalize();
    this.body.velocity.x = this.#moveDirection.x * CHASE_SPEED;
    this.body.velocity.z = this.#moveDirection.z * CHASE_SPEED;
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    this.body.velocity.set(0, 0, 0);
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      alive: this.alive,
      detected: this.detected,
      health: this.health,
      position: this.mesh.position.toArray(),
    };
  }

  dispose(): void {
    this.#scanHandle?.cancel();
    this.body.dispose();
    this.mesh.removeFromParent();
  }
}

