      new RigidBody3D({
        collisionLayer: WORLD_LAYER,
        collisionMask: PLAYER_LAYER | HOSTILE_LAYER | FRIENDLY_LAYER,
        object,
        physics: ctx.physics,
        shape,
        type: "fixed",
      });
    arenaBody(arena.floor, CollisionShape3D.box(22, 0.4, 20));
